const S = W.store;
// running: the power bar is how many of the six fans run. Inside temperature = outside + the hens' own heat (less with
// more air), minus the pads' cooling (when the fans pull air through them on a hot day). Hens are best at 21–27 °C; above
// 30 they pant, eat less, lay fewer eggs. Over the limit (all six at full, belts tight): two fans' overload relays trip.
// 🚩 "summer": a hot dry day (outside up to 42 °C): the pads and the foggers work hard. 🚩 "collect": the egg belts run.
const sign = W.group();
sign.add(W.text('JARVIS · లేయర్ కోళ్ళ ఫారం', { size: 70, at: [-3017, 380, 0], color: '#1f3a5a', bg: '#e8e2d0', rot: [0, -90, 0] }));
