W.throttle({ label: 'ఫ్యాన్లు', rise: 0.35, fall: 0.35, start: 0.5 });
const fv = W.sound({ kind: 'fans', label: 'ఎగ్జాస్ట్ ఫ్యాన్లు', gain: 0.9 });
const bv = W.sound({ kind: 'chain', label: 'గుడ్ల బెల్ట్‌లు', gain: 0.35 });
const pv = W.sound({ kind: 'water', label: 'కూలింగ్ ప్యాడ్‌లు', gain: 0.25 });
const hv = W.sound({ kind: 'swoosh', label: 'కోళ్ళు', gain: 0.18, f0: 3 });
const M = new THREE.Matrix4(), Q = new THREE.Quaternion(), P = new THREE.Vector3(), Z = new THREE.Vector3(), Y = new THREE.Vector3(0, 1, 0);
let hudT = 0, headT = 0, fk = 0, tin = 26, collected = 0, n = 0;
S.st = { air: 0, pads: 0, fog: 0, belt: 0 };
const sm = (a, b, v) => { const x = Math.min(1, Math.max(0, (v - a) / (b - a))); return x * x * (3 - 2 * x); };
W.onTick((t, dt) => {
  const s = W.env.spool, over = W.env.over, summer = W.env.flag('summer'), collect = W.env.flag('collect'), hr = W.env.hour == null ? 12 : W.env.hour;
  n = s > 0.02 ? Math.max(1, Math.round(6 * Math.min(1, s))) : 0;
  if (over) n = Math.min(n, 4);
  fk += (n / 6 - fk) * Math.min(1, dt * 1.2);
  S.fans.forEach((f, i) => { f.rotation.x += dt * 20 * (i < n ? 1 : 0); });
  const sun = Math.max(0, Math.sin(((hr - 6) / 12) * Math.PI)), tout = summer ? 31 + 11 * sun : 24 + 8 * sun;
  const pads = fk > 0.3 && tout > 28 ? 1 : 0, fog = summer && tin > 31 ? 1 : 0;
  const target = tout + 8 * Math.pow(1 - fk, 1.5) - pads * 0.55 * (tout - 21) * fk - fog * 2;
  tin += (target - tin) * Math.min(1, dt * 0.4);
  S.st.air = fk; S.st.pads = pads; S.st.fog = fog; S.st.belt = collect ? 1 : 0;
  S.padTex.offset.y -= dt * 0.05 * pads; S.padM.color.setRGB(1 - 0.25 * pads, 1 - 0.2 * pads, 1 - 0.1 * pads);
  S.ctlScreen.material.emissive.set(tin > 30 ? 0xff5a3a : 0x3aff8a);
  // the egg belts: the eggs move along to the end when collecting, and drop onto the cross belt
  const laid = 9000 * sm(5, 12, hr) * (tin > 30 ? 0.8 : 1);
  if (collect) collected = Math.min(laid, collected + dt * 160);
  const show = Math.max(0, Math.min(1, (laid - collected) / 3000 + 0.25));
  S.tiers.forEach((c, ti) => { for (let k = 0; k < S.NE; k++) {
    const i = ti * S.NE + k;
    if (collect) S.eggU[i] = (S.eggU[i] + dt * 0.03) % 1;
    const vis = ((i * 0.37) % 1) < show ? 1 : 0;
    S.eggs.setMatrixAt(i, M.compose(P.set(S.X0 + S.eggU[i] * S.L, c.y + 2, c.fz + c.s * 5), Q.setFromAxisAngle(Y, 1.57), Z.set(2.3 * vis, 2.9 * vis, 2.3 * vis)));
