// Inside a cooling pad, much larger than life: thin paper sheets with slanted flutes, crossing each other (a honeycomb).
// A pipe on top keeps them wet; the water runs down the flutes as a thin film. The fans pull the hot outside air through:
// it gives its heat to dry a little of the water (evaporation), so it comes out the other side several degrees cooler,
// a little damper. The same thing cools you when wind blows on wet skin.
const paper = W.plastic('#b8874a', { rough: 0.95 }), wet = new THREE.MeshStandardMaterial({ color: 0x9c6c3a, roughness: 0.3, metalness: 0 });
const sheets = W.group();
for (let i = 0; i < 7; i++) {
  const g = W.group({ at: [0, 0, -150 + i * 50] });
  for (let k = -6; k <= 6; k++) g.add(W.mesh(W.box(4, 360, 30), i % 2 ? paper : wet, { at: [k * 40, 0, 0], rot: [0, 0, (i % 2 ? 1 : -1) * 30] }));
  g.add(W.mesh(W.box(560, 380, 2), new THREE.MeshStandardMaterial({ color: 0xc89a5a, roughness: 0.95, transparent: true, opacity: 0.25, side: THREE.DoubleSide }), { at: [0, 0, 22] }));
  sheets.add(g);
}
W.add(sheets, { label: 'తేమ కాగితం పొరలు' });
const top = W.group();
top.add(W.mesh(W.cyl(14, 14, 380, 12), W.paint('#3a6ea5'), { at: [0, 210, 0], rot: [90, 0, 0] }));
W.add(top, { label: 'నీటి పైపు' });
const NW = 70, drops = new THREE.InstancedMesh(new THREE.SphereGeometry(1, 6, 4), new THREE.MeshStandardMaterial({ color: 0x4fb3ff, roughness: 0.1, transparent: true, opacity: 0.85 }), NW);
const dg = W.group(); dg.add(drops); W.add(dg, { label: 'నీటి పొర' });
const NA = 110, air = new THREE.InstancedMesh(new THREE.SphereGeometry(1, 8, 6), new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.6, transparent: true, opacity: 0.8 }), NA);
const ag = W.group(); ag.add(air); W.add(ag, { label: 'గాలి' });
const M = new THREE.Matrix4(), Q = new THREE.Quaternion(), P = new THREE.Vector3(), Z = new THREE.Vector3(), C = new THREE.Color();
const du = Array.from({ length: NW }, (_, i) => i / NW), au = Array.from({ length: NA }, (_, i) => i / NA);
W.onTick((t, dt) => {
  const k = Math.max(0.2, W.env.spool);
  for (let i = 0; i < NW; i++) {
    du[i] = (du[i] + dt * 0.25) % 1;
    const col = (i % 13) - 6, sl = (i % 7) - 3;
