    air.setMatrixAt(i, M.compose(P, Q, Z.setScalar(6)));
    air.setColorAt(i, C.set(u < 0.35 ? '#ff7a2a' : u > 0.65 ? '#5ab8ff' : '#ffd08a').lerp(new THREE.Color(u < 0.35 ? '#ff7a2a' : '#5ab8ff'), 0.3));
  }
